```javascript
import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  MeshPhysicalNodeMaterial,
  ExtrudeGeometry,
  OctahedronGeometry,
  PlaneGeometry,
  Shape,
  DirectionalLight,
  Group,
  Mesh,
  Color,
  MathUtils
} from 'three/webgpu';
import { uv, vec3, mix, smoothstep, uniform, Fn } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;

  // --- MAIN GROUP ---
  const group = new THREE.Group();
  group.name = 'glass-prism-refraction';

  // --- 1. BACKDROP PLANE ---
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  backdropGeo.translate(0, 0, -2.5);

  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.side = THREE.DoubleSide;

  const g0 = uniform('vec3', new Color('#0b0b10'));
  const g1 = uniform('vec3', new Color('#12121a'));
  const g2 = uniform('vec3', new Color('#16161d'));

  const gradientNode = Fn(() => {
    const y = uv().y;
    const c1 = mix(g0, g1, smoothstep(0.0, 0.6, y));
    const c2 = mix(c1, g2, smoothstep(0.6, 1.0, y));
    return c2;
  })();
  backdropMat.colorNode = gradientNode;

  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  group.add(backdrop);

  // --- 2. PRISM GROUP (rotates with depth-rotate) ---
  const prismGroup = new THREE.Group();
  prismGroup.rotation.set(0, MathUtils.degToRad(20), MathUtils.degToRad(12), 'XYZ');
  group.add(prismGroup);

  // --- 2a. TRIANGULAR PRISM ---
  const side = 1.2;
  const triHeight = side * Math.sqrt(3) / 2;
  const shape = new Shape();
  shape.moveTo(0, triHeight / 2);
  shape.lineTo(-side / 2, -triHeight / 2);
  shape.lineTo(side / 2, -triHeight / 2);
  shape.closePath();

  const extrudeSettings = { depth: 1.8, bevelEnabled: false };
  const prismGeo = new ExtrudeGeometry(shape, extrudeSettings);
  prismGeo.rotateY(Math.PI / 2);
  prismGeo.center();

  const prismMat = new MeshPhysicalNodeMaterial();
  prismMat.transmission = 1.0;
  prismMat.thickness = 0.9;
  prismMat.ior = 1.55;
  prismMat.dispersion = 0.18;
  prismMat.iridescence = 1.0;
  prismMat.iridescenceIOR = 1.3;
  prismMat.iridescenceThicknessRange = [120, 480];
  prismMat.roughness = 0.08;
  prismMat.clearcoat = 0.25;
  prismMat.clearcoatRoughness = 0.1;
  prismMat.attenuationColor = new Color('#e8ecf2');
  prismMat.attenuationDistance = 2.5;
  prismMat.color = new Color('#e8ecf2');
  prismMat.envMapIntensity = 1.0;

  const prismMesh = new THREE.Mesh(prismGeo, prismMat);
  prismMesh.castShadow = true;
  prismMesh.receiveShadow = true;
  prismGroup.add(prismMesh);

  // --- 2b. EMISSIVE CORE (octahedron) ---
  const coreGeo = new OctahedronGeometry(0.35);
  const coreMat = new MeshStandardNodeMaterial();
  coreMat.color = new Color('#ff2a38');
  coreMat.emissive = new Color('#ff2a38');
  coreMat.emissiveIntensity = 2.2;
  const coreMesh = new THREE.Mesh(coreGeo, coreMat);
  prismGroup.add(coreMesh);

  // --- 2c. BACK RIM LIGHT ---
  const rimLight = new DirectionalLight(0xb0c0e0, 1.2);
  rimLight.position.set(-2, 1, 2);
  rimLight.target.position.set(0, 0, 0);
  prismGroup.add(rimLight);
  prismGroup.add(rimLight.target);

  // --- 3. CAUSTIC STREAK (floor plane) ---
  const causticGeo = new PlaneGeometry(2.4, 0.5);
  const causticMat = new MeshBasicNodeMaterial();
  causticMat.transparent = true;
  causticMat.opacity = 0.35;
  causticMat.side = THREE.DoubleSide;

  const cs0 = uniform('vec3', new Color('#ff2a38'));
  const cs1 = uniform('vec3', new Color('#e8ecf2'));
  const cs2 = uniform('vec3', new Color('#9fb0c4'));

  const causticNode = Fn(() => {
    const x = uv().x;
    const c1 = mix(cs0, cs1, smoothstep(0.2, 0.5, x));
    const c2 = mix(c1, cs2, smoothstep(0.5, 0.8, x));
    return c2;
  })();
  causticMat.colorNode = causticNode;

  const causticMesh = new THREE.Mesh(causticGeo, causticMat);
  causticMesh.position.set(0, -1.1, 0);
  causticMesh.rotation.x = -Math.PI / 2;
  group.add(causticMesh);

  // --- 4. TEXT ---
  const headline = ctx.fontAtlas.createText('Light, machined.', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'left'
  });
  headline.position.set(0, -1.75, 0);
  // Scale to fit scene: 68px -> scene units ~0.34? Use approximate scale factor.
  const textScale = 0.005;
  headline.scale.set(textScale, textScale, textScale);
  group.add(headline);

  const caption = ctx.fontAtlas.createText('SAPPHIRE OVER DIAL / ZERO DISTORTION', {
    fontSize: 18,
    color: '#9fb0c4',
    align: 'left',
    letterSpacing: 0.08
  });
  caption.position.set(0, -2.25, 0);
  caption.scale.set(textScale, textScale, textScale);
  group.add(caption);

  // --- 5. INTERACTIVE HIT AREA (transparent plane for hover) ---
  const hitMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0, side: THREE.DoubleSide });
  const hitGeo = new PlaneGeometry(2.4, 1.6);
  const hitMesh = new THREE.Mesh(hitGeo, hitMat);
  hitMesh.position.set(0, 0, 0.5); // in front of prism
  group.add(hitMesh);

  // --- 6. CINEMATIC PRIMITIVE: depth-rotate on prismGroup ---
  const depthRotateResult = ctx.primitives['depth-rotate'](prismGroup, { maxDeg: 10 });

  // --- 7. CAUSTIC STREAK HOVER ANIMATION ---
  const causticTL = gsap.timeline({ paused: true });
  causticTL.to(causticMesh.scale, {
    x: 1.08,
    z: 1.08,
    duration: 0.35,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)',
  });
  causticTL.reverse();

  group.userData.handlers = {
    pointerenter: () => {
      causticTL.play();
    },
    pointerleave: () => {
      causticTL.reverse();
    }
  };

  // --- 8. USERDATA CLEANUP ---
  group.userData.cleanup = () => {
    // Dispose geometries and materials
    backdropGeo.dispose();
    backdropMat.dispose();
    prismGeo.dispose();
    prismMat.dispose();
    coreGeo.dispose();
    coreMat.dispose();
    causticGeo.dispose();
    causticMat.dispose();
    hitGeo.dispose();
    hitMat.dispose();

    // Kill GSAP timelines
    causticTL.kill();

    // Kill depth-rotate primitive
    depthRotateResult.cleanup();

    // Remove all children and dispose
    group.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material?.dispose();
        }
      }
    });
  };

  return group;
}
